PUBLIC BRIEF: {"buyer":"Hemisfair Park Area Redevelopment Corporation","exclusions":["Historic July 2, 2021 proposal deadline and 2021/2023 rollout dates are not current commitments.","QR badge installation is assigned to HPARC staff, not the vendor. Tower Park and additions for future phases, historic structures or amenities are potential future scope, not guaranteed baseline work.","Spanish translation is conditional. The all-model device wording is retained as a requested target, not proof of feasible or tested support.","Brand assets, donor media/permissions, CMS accounts and release credentials are unavailable. No physical work, deployment, donor publication or procurement is authorized; FAQ output would be a proposed draft only."],"id":"hemisfair-augmented-reality-tree-recognition-2021","requirements":[{"brick":"provision","id":"R1","owner":"human_required","text":"Develop a Hemisfair-branded, Hemisfair-owned AR app for iOS and Android targeting all iPhone, iPad and Android models as requested and covering the two named parks."},{"brick":"provision","id":"R2","owner":"human_required","text":"Use QR codes and GPS to activate the experience; provide entrance/tree codes, custom badge design and the first 250 physical QR badges for HPARC staff to install."},{"brick":"provision","id":"R3","owner":"human_required","text":"Show donor-recognition photos, text and optional recorded tributes near claimed trees; route unclaimed-tree scans to tree-planting program information."},{"brick":"provision","id":"R4","owner":"human_required","text":"Provide recognition-name search, interactive tree maps and walking directions, program information, donation links and sponsor recognition."},{"brick":"validate","id":"R5","owner":"human_required","text":"Meet the requested ADA digital-accessibility standards, including captions, distinguishable controls and minimal flashing; consider Spanish translation where feasible."},{"brick":"provision","id":"R6","owner":"blocked_private_input","text":"Provide an easy-to-learn staff content-management system for tree donor records, define photo/audio/text parameters and provide a way to acquire additional QR badges."},{"brick":"report","id":"R7","owner":"human_required","text":"Train two HPARC staff members to maintain the system."},{"brick":"draft","id":"R8","owner":"agent_draft","text":"Prepare a proposed AR-app FAQ for publication on Hemisfair\u2019s website."},{"brick":"remediate","id":"R9","owner":"human_required","text":"Provide a one-year service and support warranty."}],"source_url":"https://hemisfair.org/wp-content/uploads/2021/06/05.25.2021-RFP-Hemisfair-Augmented-Reality-Project.pdf","summary":"Historical June 2021 RFP for a Hemisfair-owned augmented-reality tree-donor app with a $50,000-$100,000 budget range and approximately 230 trees in Yanaguana Garden and Civic Park. The requested pilot launch was December 1, 2021, with Civic Park rollout in 2023.","title":"Hemisfair Augmented Reality Project: Tree Donor Recognition"}
